/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Budget for ≤ 200 records:  2 SOQL, 1 DML  (before + after combined).
 */
public with sharing class ContactTriggerHandler {

    /* ------------------------------------------------------------------ */
    /*  BEFORE INSERT / BEFORE UPDATE                                      */
    /*  • MailingCountry ← Account.BillingCountry  (when blank)           */
    /*  • LeadSource     ← Account.AccountSource    (insert only, blank)  */
    /* ------------------------------------------------------------------ */
    public static void handleBefore() {

        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // --- 1 SOQL --------------------------------------------------------
        Map<Id, Account> acctById = new Map<Id, Account>(
            new List<Account>(
                [SELECT Id, BillingCountry, AccountSource
                 FROM   Account
                 WHERE  Id IN :accountIds]
            )
        );

        Boolean isInsert = Trigger.isInsert;

        for (Contact c : Trigger.new) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = acctById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /*  AFTER INSERT                                                       */
    /*  If a new Contact carries a Phone and its Account has none,       */
    /*  copy the phone to the Account.  Only the FIRST contact in        */
    /*  trigger order for a given Account performs the write.             */
    /* ------------------------------------------------------------------ */
    public static void handleAfterInsert() {

        // Only care about contacts that could possibly drive a phone update.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // --- 2nd SOQL ------------------------------------------------------
        Map<Id, Account> acctById = new Map<Id, Account>(
            new List<Account>(
                [SELECT Id, Phone
                 FROM   Account
                 WHERE  Id IN :accountIds]
            )
        );

        Set<Account> accountsToUpdate = new Set<Account>();

        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            Account a = acctById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            // Because we mutate the SAME object in the map, once the first
            // contact writes a phone the subsequent contacts for the same
            // account will see a non-blank value and skip – replicating the
            // "re-query" behaviour of the original per-record code.
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            // --- 1 DML -----------------------------------------------------
            update accountsToUpdate;
        }
    }
}
```

### Why the "first-contact-wins" semantics are preserved

In the original trigger every iteration re-queried the Account, so after contact #1 updated the phone, contact #2's fresh query saw the new non-blank value and skipped. In the refactored handler all contacts share **one** `Account` instance from `acctById`. Contact #1 writes into that object; when the loop reaches contact #2 (same `AccountId`) the check `String.isBlank(a.Phone)` reads the already-mutated value, fails, and skips — identical outcome without a second query.

### Budget verification (200 contacts)

| | SOQL | DML |
|---|---|---|
| `handleBefore` | 1 (single `IN` query) | 0 |
| `handleAfterInsert` | 1 (single `IN` query) | 1 (single `update`) |
| **Total** | **2** | **1** |

