public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Set LeadSource to Web where blank (applied to every lead before insertion logic)
        for (Lead l : leads) {
            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }
        }

        // Identify duplicates and build the insert list, preserving input-order mapping
        Set<String> seenEmails = new Set<String>();
        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertInputIndex = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];

            String emailKey = null;
            if (String.isNotBlank(l.Email)) {
                emailKey = l.Email.trim().toLowerCase();
            }

            // A lead with a non-null email that matches a previously-seen email is a duplicate
            if (emailKey != null && seenEmails.contains(emailKey)) {
                result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                continue;
            }

            if (emailKey != null) {
                seenEmails.add(emailKey);
            }

            toInsert.add(l);
            toInsertInputIndex.add(i);
        }

        // Single DML statement, allow partial success
        if (!toInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(toInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Integer inputIdx = toInsertInputIndex[j];

                if (saveResults[j].isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(saveResults[j].getId());
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error err : saveResults[j].getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(inputIdx, String.join(messages, '; '));
                }
            }
        }

        return result;
    }
}
