/**
 * Schedulable Apex class that purges old FB_Integration_Log__c records.
 *
 * • Non-ERROR logs (including blank/null Level__c) are deleted after 30 days.
 * • ERROR logs are retained until they are older than 180 days.
 */
public with sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        Datetime thirtyDaysAgo = Datetime.now().addDays(-30);
        Datetime oneHundredEightyDaysAgo = Datetime.now().addDays(-180);

        // Iterate in chunks of 10 000 to stay within governor limits.
        while (true) {
            List<FB_Integration_Log__c> batch = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (
                        CreatedDate < :thirtyDaysAgo
                        AND (Level__c != 'ERROR' OR Level__c = NULL)
                    )
                    OR (
                        CreatedDate < :oneHundredEightyDaysAgo
                        AND Level__c = 'ERROR'
                    )
                LIMIT 10000
            ];

            if (batch.isEmpty()) {
                break;
            }

            delete batch;
        }
    }

    /**
     * Convenience method to schedule the nightly purge.
     * Runs every day at 02:00 server time.
     *
     * @return The CronTrigger record Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        String cronExpr = '0 0 2 * * ?';
        String jobName  = 'Log purge (nightly)';
        return System.schedule(jobName, cronExpr, new LogPurgeJob());
    }
}
