    // ── Validation hooks ──────────────────────────────────────────────

    public override void onBeforeInsert() {
        validateAmount();
    }

    public override void onBeforeUpdate() {
        validateAmount();
        validateWonOpportunityAmount();
    }

    // ── Private helpers ───────────────────────────────────────────────

    /**
     * Rule 1 (insert + update): Amount must not be negative.
     */
    private void validateAmount() {
        for (SObject record : (List<SObject>) records) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2 (update only): once an opportunity is ALREADY Closed Won,
     * its Amount must not change.
     *
     * Closing an opportunity AS WON in the same transaction while also
     * changing Amount is allowed (the old stage was not Closed Won).
     */
    private void validateWonOpportunityAmount() {
        for (SObject record : (List<SObject>) records) {
            Opportunity opp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);

            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && opp.Amount != oldOpp.Amount) {

                error('Amount cannot change on a won opportunity.',
                      opp, Opportunity.Amount);
            }
        }
    }
}
