public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        fields.addAll(getCreditReviewFields());
        return fields;
    }

    public override fflib_ISObjectSelector.DataAccessMode getDataAccessMode() {
        return fflib_ISObjectSelector.DataAccessMode.WITH_USER_MODE;
    }

    private static List<Schema.SObjectField> sCreditReviewFields;

    private List<Schema.SObjectField> getCreditReviewFields() {
        if (sCreditReviewFields != null) {
            return sCreditReviewFields;
        }

        List<Schema.SObjectField> result = new List<Schema.SObjectField>();
        Map<String, Schema.SObjectField> fieldMap =
            Schema.SObjectType.Account.fields.getMap();

        Map<String, Schema.FieldSet> fieldSetMap =
            Schema.SObjectType.Account.fieldSets.getMap();

        if (fieldSetMap != null && fieldSetMap.containsKey('Credit_Review')) {
            Schema.FieldSet fs = fieldSetMap.get('Credit_Review');
            if (fs != null) {
                for (Schema.FieldSetMember fsm : fs.getAvailableFields()) {
                    String fieldName = fsm.getFieldPath();
                    if (fieldName.contains('.')) {
                        fieldName = fieldName.substringAfterLast('.');
                    }
                    if (fieldMap.containsKey(fieldName)) {
                        result.add(fieldMap.get(fieldName));
                    }
                }
            }
        }

        sCreditReviewFields = result;
        return result;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        // Parent field names from this selector
        List<String> acctFieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            acctFieldNames.add(f.getDescribe().getName());
        }

        // Child field names driven by the existing ContactsSelector
        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contFieldNames = new List<String>();
        for (Schema.SObjectField f : contactsSelector.getSObjectFieldList()) {
            contFieldNames.add(f.getDescribe().getName());
        }

        String soql = 'SELECT ' + String.join(acctFieldNames, ',') +
                      ', (SELECT ' + String.join(contFieldNames, ',') +
                      ' FROM Contacts) FROM Account WITH USER_MODE' +
                      ' WHERE Id IN :accountIds';

        return Database.query(soql);
    }
}
