public inherited sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities via the Selector
        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Filter to those not already Closed Won and apply the update values
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // Single unit of work – DML then (only on success) event publish
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        uow.registerDirty(toClose);

        // Queue one Deal_Won__e per closed opportunity; committed only after DML succeeds
        for (Opportunity opp : toClose) {
            uow.publishEvent(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c         = opp.Amount
            ));
        }

        // commit() performs the UPDATE first; if it throws, events are never
        // published and the exception propagates to the caller.
        uow.commit();

        return toClose.size();
    }
}
