public with sharing class CasePriorityHandler {

    /**
     * Before-insert handler: escalate priority for cases whose Account
     * Rating is 'Hot'.  Safe for single-record (Email-to-Case) and
     * bulk (ERP batch) inserts up to the platform's 200-row DML cap.
     */
    public static void onBeforeInsert(List<Case> newCases) {

        // 1 – Collect the Account Ids we actually need to check.
        //    One Set lookup per record, no SOQL inside the loop.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // 2 – Single bulk query: pull only the accounts that are Hot.
        //    One SOQL regardless of whether there are 1 or 200 accounts.
        Map<Id, Account> hotAccounts = new Map<Id, Account>(
            [SELECT Rating
               FROM Account
              WHERE Id = :accountIds
                AND Rating = 'Hot']
        );

        // 3 – Walk the new cases and bump priority when needed.
        for (Case c : newCases) {
            if (c.AccountId != null && hotAccounts.containsKey(c.AccountId)) {
                c.Priority = 'High';
            }
            // All other cases (null Account, non-Hot Account) keep
            // whatever Priority they were created with.
        }
    }
}
