/**
 * ErpCustomerSync
 *
 * • Static entry-point called from AccountTrigger.
 * • Enqueues a Queueable job so the HTTP callout executes in an
 *   asynchronous context (callouts are illegal inside triggers).
 * • The Queueable builds a JSON array of 1–200 customer objects and
 *   POSTs it to the ERP in a single request via the "ERP" Named
 *   Credential.
 *
 * One request per trigger batch → the ERP team can trace every account
 * by its 18-char Salesforce Id inside the array.
 */
public with sharing class ErpCustomerSync implements Queueable {

    // ---- Guard to avoid enqueuing duplicate jobs in one transaction ----
    private static Boolean dispatched = false;

    // ---- Queueable state (must be JSON-serialisable) ------------------
    private final List<Id> accountIds;

    // ---- Constructor (called from the static push method) --------------
    public ErpCustomerSync(List<Id> ids) {
        this.accountIds = ids;
    }

    // ---------------------------------------------------------------------
    //  Entry point invoked by AccountTrigger
    // ---------------------------------------------------------------------
    public static void push(List<Account> accounts) {

        if (dispatched || accounts.isEmpty()) {
            return;
        }
        dispatched = true;

        List<Id> ids = new List<Id>(accounts.size());
        for (Account acct : accounts) {
            ids.add(acct.Id);
        }

        // One async job per trigger batch – carries all new account Ids.
        System.enqueueJob(new ErpCustomerSync(ids));
    }

    // ---------------------------------------------------------------------
    //  Queueable execution – runs in a separate, async transaction
    //  where synchronous HTTP callouts ARE permitted (max 250).
    // ---------------------------------------------------------------------
    public void execute(QueueableContext context) {

        // Bulk-safe single query; handles 1 → 200 records.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ];

        // Build the JSON payload:  [{"salesforceId":…,"name":…,"country":…}, …]
        List<Map<String, Object>> payload = new List<Map<String, Object>>(accounts.size());

        for (Account acct : accounts) {
            // BillingCountry may be null or blank → serialise as JSON null.
            String country = String.isBlank(acct.BillingCountry)
                ? null
                : acct.BillingCountry;

            payload.add(new Map<String, Object>{
                'salesforceId' => acct.Id,          // 18-char Id
                'name'         => acct.Name,
                'country'      => country           // null when blank
            });
        }

        // ---- Single POST to the ERP via the Named Credential ----
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));
        req.setTimeout(120000); // 120 s – well within the 120 s async ceiling

        Http http = new Http();
        http.send(req);

        // Error handling / retries intentionally omitted (out of scope).
    }
}
```

