/**
 * Creates a follow-up Task for each Opportunity passed in.
 *
 * Each Task is inserted individually inside a try/catch so that a validation-rule
 * rejection on one Opportunity's Task does not prevent the remaining Tasks from
 * being created.
 *
 * Returns the set of Opportunity Ids whose Task could NOT be created.
 *
 * NOTE ON GOVERNOR LIMITS:
 * This implementation intentionally performs one DML per record (as requested) to
 * guarantee per-record isolation from validation-rule failures.  Salesforce allows
 * at most 150 DML statements per synchronous transaction.  With pipeline reviews
 * of 150–250 opportunities this will exceed that limit in a single synchronous call.
 * In production, either chunk the call to ≤ 149 records per invocation, or switch
 * to a single `Database.insert(allTasks, false)` and inspect the SaveResult list
 * (see comment at the bottom of this file for that variant).
 */
public with sharing class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {

        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk-safe query: one SOQL regardless of input size.
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            new List<Opportunity>(
                [
                    SELECT Id, Name, OwnerId
                    FROM Opportunity
                    WHERE Id IN :opportunityIds
                ]
            )
        );

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null) {
                // Id not found (deleted, wrong SObject, etc.) – treat as failure.
                failedOpportunityIds.add(oppId);
                continue;
            }

            Task followUp = new Task();
            followUp.WhatId       = opp.Id;
            followUp.OwnerId      = opp.OwnerId;
            followUp.Subject      = 'Follow up: ' + opp.Name;
            followUp.ActivityDate = Date.today().addDays(7);
            followUp.Status       = 'Not Started';
            followUp.Priority     = 'Normal';

            try {
                // Individual insert so that a validation-rule failure on this one
                // Task does not roll back the Tasks already inserted, and the
                // remaining iterations continue.
                insert followUp;
            } catch (Exception e) {
                // Covers DmlException (validation rules, required fields, etc.)
                // and any other unexpected failure.
                failedOpportunityIds.add(opp.Id);
            }
        }

        return failedOpportunityIds;
    }

    /*
     * BULK-SAFE VARIANT (suggested for production when N > 149):
     *
     *   List<Task> tasks = new List<Task>();
     *   List<Id>    oppIds = new List<Id>();
     *
     *   for (Id oppId : opportunityIds) { ... build Task ... tasks.add(t); oppIds.add(oppId); }
     *
     *   Database.SaveResult[] results = Database.insert(tasks, false);
     *
     *   for (Integer i = 0; i < results.size(); i++) {
     *       if (!results[i].isSuccess()) {
     *           failedOpportunityIds.add(oppIds[i]);
     *       }
     *   }
     *
     * This uses exactly one DML statement and is immune to the 150-DML limit,
     * while still allowing partial success (allOrNone = false).
     */
}
