/**
 * Before-insert handler for OpportunityLineItem.
 * Defaults Discount to the product's standard discount (via PricingRules)
 * when the rep left it null. An explicit 0 is treated as "rep typed it in"
 * and is preserved.
 *
 * Bulk-safe: one SOQL regardless of record count (tested up to 200-line
 * CPQ quote imports).
 */
public with sharing class LineItemDiscountHandler {

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // ---- 1. Collect the product Ids that actually need a default ----
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null && oli.Product2Id != null) {
                productIds.add(oli.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // ---- 2. ONE query for all referenced products ----
        Map<Id, Product2> productMap = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        // ---- 3. Delegate the family→discount mapping to PricingRules ----
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount != null) {
                continue;                       // rep typed a value (even 0) – keep it
            }
            Product2 product = productMap.get(oli.Product2Id);
            if (product == null) {
                continue;                       // product not found – leave null
            }
            oli.Discount = PricingRules.standardDiscountForFamily(product.Family);
        }
    }
}
