```apex
/**
 * CaseTrigger – after-update handler.
 * Detects cases that transition from open → closed (IsClosed false → true)
 * and have a Contact. Enqueues a CaseSurveyJob (batched ≤ 50 per enqueue to
 * respect the 50-Queueable-per-transaction platform limit).
 */
trigger CaseTrigger on Case (after update) {

    if (Trigger.isAfter && Trigger.isUpdate) {

        List<Id> newlyClosedCaseIds = new List<Id>();

        for (Case newCase : Trigger.new) {
            Case oldCase = Trigger.oldMap.get(newCase.Id);

            // Transition check: was open, now closed, and has a contact
            if (newCase.IsClosed
                && !oldCase.IsClosed
                && newCase.ContactId != null) {

                newlyClosedCaseIds.add(newCase.Id);
            }
        }

        if (newlyClosedCaseIds.isEmpty()) {
            return;
        }

        // Platform limit: max 50 Queueable jobs per transaction.
        // Chunk so that a 200-record bulk close (nightly API cleanup)
        // produces 4 jobs instead of blowing up with a LimitException.
        final Integer BATCH_SIZE = 50;

        for (Integer i = 0; i < newlyClosedCaseIds.size(); i += BATCH_SIZE) {
            Integer remaining = newlyClosedCaseIds.size() - i;
            Integer chunkSize = Math.min(BATCH_SIZE, remaining);

            List<Id> batch = newlyClosedCaseIds.getRange(i, chunkSize);
            System.enqueueJob(new CaseSurveyJob(batch));
        }
    }
}
```

