```javascript
import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_QUERY_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    @track contacts = [];
    error = null;

    _debounceTimer = null;
    _requestId = 0;
    _connected = true;

    connectedCallback() {
        this._connected = true;
    }

    disconnectedCallback() {
        this._connected = false;
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
    }

    handleChange(event) {
        const rawValue = event.target.value || '';
        const searchTerm = rawValue.trim();

        // Cancel any pending debounced search
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        // Too short – clear results, don't call Apex
        if (searchTerm.length < MIN_QUERY_LENGTH) {
            this.contacts = [];
            this.error = null;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._performSearch(searchTerm);
        }, DEBOUNCE_MS);
    }

    _performSearch(searchTerm) {
        const requestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore if a newer request has been issued
                if (requestId !== this._requestId) { return; }
                // Ignore if component was removed from the page
                if (!this._connected) { return; }

                this.contacts = result;
                this.error = null;
