import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE,
    MessageContext
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    subscription = null;
    recordId = null;
    _context = null;

    /* ------------------------------------------------------------------ */
    /*  Message-Service wiring                                             */
    /* ------------------------------------------------------------------ */

    @wire(MessageContext)
    handleMessageContext(result) {
        // Tear down any existing subscription before re-establishing
        this._cleanupSubscription();

        if (result.data) {
            this._context = result.data;
            this._subscribe(result.data);
        }
    }

    // Handles re-insertion (e.g. tab closed then reopened) where the
    // wire adapter will NOT re-fire because the component instance was
    // kept alive but simply disconnected / reconnected.
    connectedCallback() {
        if (!this.subscription && this._context) {
            this._subscribe(this._context);
        }
    }

    disconnectedCallback() {
        this._cleanupSubscription();
    }

    /* ------------------------------------------------------------------ */
    /*  Channel helpers                                                    */
    /* ------------------------------------------------------------------ */

    _subscribe(context) {
        this.subscription = subscribe(
            ACCOUNT_SELECTED,
            context,
            this._handleMessage,
            { scope: APPLICATION_SCOPE }
        );
    }

    _cleanupSubscription() {
        if (this.subscription) {
            unsubscribe(this.subscription, this._handleMessage);
            this.subscription = null;
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Message listener                                                   */
    /* ------------------------------------------------------------------ */

    _handleMessage = (message) => {
        this.recordId = message.recordId;
    };

    /* ------------------------------------------------------------------ */
    /*  Clear-selection button handler                                     */
    /* ------------------------------------------------------------------ */

    handleClearSelection() {
        if (this._context) {
            publish(ACCOUNT_SELECTED, this._context, { recordId: null });
        }
    }
}
