import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFieldChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        // Step 1: Custom email domain validation (before reportValidity)
        const emailInput = this.template.querySelector('[data-field="email"]');
        const domain = this.getDomain(this.email);

        if (PERSONAL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: Call reportValidity on EVERY input so all messages appear at once
        const fullNameInput = this.template.querySelector('[data-field="fullName"]');
        const companyInput = this.template.querySelector('[data-field="company"]');

        const fullNameValid = fullNameInput.reportValidity();
        const emailValid = emailInput.reportValidity();
        const companyValid = companyInput.reportValidity();

        // Step 3: If any input is invalid, stop
        if (!fullNameValid || !emailValid || !companyValid) {
            return;
        }

        // Step 4: Call the Apex method imperatively
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }

    getDomain(email) {
        if (!email || !email.includes('@')) {
            return '';
        }
        return email.split('@')[1].toLowerCase();
    }
}
