import { LightningElement, api } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _selectedValue = undefined;
    _activeIndex = -1;
    _uid = `lb${++uidCounter}${Math.random().toString(36).slice(2, 8)}`;

    // ------------------------------------------------------------------
    // Public value API – setter keeps active in sync with external changes
    // ------------------------------------------------------------------
    @api
    get value() {
        return this._selectedValue;
    }

    set value(newValue) {
        this._selectedValue = newValue;
        this._syncActiveToValue();
    }

    // ------------------------------------------------------------------
    // Lifecycle – covers the case where value is set before options
    // ------------------------------------------------------------------
    connectedCallback() {
        this._syncActiveToValue();
    }

    // ------------------------------------------------------------------
    // Template getters
    // ------------------------------------------------------------------
    get hasOptions() {
        return Array.isArray(this.options) && this.options.length > 0;
    }

    get activeDescendantId() {
        if (this._activeIndex >= 0 && this.hasOptions) {
            return `${this._uid}-${this._activeIndex}`;
        }
        return undefined;
    }

    get listboxItems() {
        if (!this.hasOptions) {
            return [];
        }
        return this.options.map((opt, index) => ({
            key: `${this._uid}-${index}`,
            id: `${this._uid}-${index}`,
            index,
            value: opt.value,
            label: opt.label,
            ariaSelected: opt.value === this._selectedValue ? 'true' : 'false'
        }));
    }

    // ------------------------------------------------------------------
    // Keyboard handler – placed on the <ul>
    // ------------------------------------------------------------------
    handleKeyDown(event) {
        const opts = this.options;
        if (!opts || opts.length === 0) return;

        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (handledKeys.indexOf(event.key) === -1) return;

        // Prevent default for the six handled keys only (Tab stays free)
        event.preventDefault();

        let idx = this._activeIndex;

        switch (event.key) {
            case 'ArrowDown':
                if (idx < opts.length - 1) {
                    this._activeIndex = idx + 1;
                }
                break;
            case 'ArrowUp':
                if (idx > 0) {
                    this._activeIndex = idx - 1;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = opts.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectIndex(this._activeIndex);
                break;
            default:
                break;
        }
    }

    // ------------------------------------------------------------------
    // Option click handler – on each <li>
    // ------------------------------------------------------------------
    handleOptionClick(event) {
        const li = event.currentTarget;
        if (!li || li.dataset.index === undefined) return;

        const index = parseInt(li.dataset.index, 10);
        if (isNaN(index)) return;

        this._activeIndex = index;
        this._selectIndex(index);
    }

    // ------------------------------------------------------------------
    // Private helpers
    // ------------------------------------------------------------------
    _syncActiveToValue() {
        const opts = this.options;
        if (opts && opts.length > 0) {
            const idx = opts.findIndex((o) => o.value === this._selectedValue);
            this._activeIndex = idx >= 0 ? idx : 0;
        } else {
            this._activeIndex = -1;
        }
    }

    _selectIndex(index) {
        const opts = this.options;
        if (!opts || index < 0 || index >= opts.length) return;

        const opt = opts[index];
        if (opt.value === this._selectedValue) return; // already selected → no event

        this._selectedValue = opt.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: opt.value },
                bubbles: true,
                composed: true
            })
        );
    }
}
