 * EmployerService
 *
 * Manages employer (Organization) affiliations for Contacts on behalf of
 * the NPSP Household Account model.  Called by the inbound web-form
 * integration to set the *current* employer for a batch of contacts.
 *
 * Design constraints honoured:
 *   • ≤ 2 SOQL queries
 *   • ≤ 2 DML statements
 *   • Bulk-safe (tested up to 200 contacts per invocation)
 */
public with sharing class EmployerService {

    /**
     * For every (Contact Id → Organization Account Id) entry:
     *   1. If the Contact already has a Current, Primary affiliation to that
     *      Organization, nothing is done (no duplicate, no churn).
     *   2. Otherwise the previous Primary employer affiliation (if any) is
     *      closed – set to Former / non-Primary / EndDate = today.
     *   3. A new Current, Primary affiliation is created.
     *   4. The Contact's npsp__Primary_Affiliation__c lookup is updated to
     *      the new Organization Account.
     *
     * @param employerByContactId  Contact Id → Organization Account Id.
     *                             Null or empty map is a no-op.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ── Guard clause ────────────────────────────────────────────────
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // ── SOQL Query 1: existing Current+Primary affiliations ─────────
        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());

        List<npe5__Affiliation__c> existingPrimaries = [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c
            FROM   npe5__Affiliation__c
            WHERE  npe5__Contact__c IN :contactIds
              AND  npe5__Status__c  = 'Current'
              AND  npe5__Primary__c = true
        ];

        // Index by Contact for O(1) lookup in the loop below.
        Map<Id, List<npe5__Affiliation__c>> primariesByContact =
            new Map<Id, List<npe5__Affiliation__c>>();

        for (npe5__Affiliation__c aff : existingPrimaries) {
            List<npe5__Affiliation__c> bucket =
                primariesByContact.get(aff.npe5__Contact__c);
            if (bucket == null) {
                bucket = new List<npe5__Affiliation__c>();
                primariesByContact.put(aff.npe5__Contact__c, bucket);
            }
            bucket.add(aff);
        }

        // ── Build the work lists (single pass, no nested SOQL/DML) ──────
        List<npe5__Affiliation__c> affiliationsToUpsert =
            new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        Date today = Date.today();

        for (Id contactId : employerByContactId.keySet()) {
            Id targetOrgId = employerByContactId.get(contactId);

            // Skip entries with no target org (defensive).
            if (targetOrgId == null) {
                continue;
            }

            List<npe5__Affiliation__c> currentPrimaries =
                primariesByContact.get(contactId);

            // ── Already primary to the target org?  Nothing to do. ──────
            Boolean alreadyPrimary = false;
            if (currentPrimaries != null) {
                for (npe5__Affiliation__c aff : currentPrimaries) {
                    if (aff.npe5__Organization__c == targetOrgId) {
                        alreadyPrimary = true;
                        break;
                    }
                }
            }
            if (alreadyPrimary) {
                continue;
            }

            // ── End the previous Primary employer (if any). ─────────────
            if (currentPrimaries != null) {
                for (npe5__Affiliation__c aff : currentPrimaries) {
                    // Only close affiliations that are NOT the new target.
                    if (aff.npe5__Organization__c != targetOrgId) {
                        // Partial-update SObject: carry Id so upsert
                        // treats it as UPDATE; leave all other fields
                        // at their DB values.
                        affiliationsToUpsert.add(new npe5__Affiliation__c(
                            Id                 = aff.Id,
                            npe5__Status__c    = 'Former',
                            npe5__Primary__c   = false,
                            npe5__EndDate__c   = today
                        ));
                    }
                }
            }

            // ── Create the new Current, Primary affiliation. ────────────
            affiliationsToUpsert.add(new npe5__Affiliation__c(
                npe5__Contact__c      = contactId,
                npe5__Organization__c = targetOrgId,
                npe5__Status__c       = 'Current',
                npe5__Primary__c      = true,
                npe5__StartDate__c    = today,
                npe5__Role__c         = 'Employee'
            ));

            // ── Repoint the Contact's primary-affiliation lookup. ───────
            contactsToUpdate.add(new Contact(
                Id                              = contactId,
                npsp__Primary_Affiliation__c    = targetOrgId
            ));
        }

        // ── DML 1: upsert affiliations (ends + creates in one call) ─────
        //      Records carrying an Id → UPDATE
        //      Records without an Id → INSERT
        if (!affiliationsToUpsert.isEmpty()) {
            Database.upsert(
                affiliationsToUpsert,
                /* allOrNone = */ false
            );
        }

        // ── DML 2: update Contacts (primary-affiliation lookup) ─────────
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
