/**
 * Service class for creating NPSP Household Accounts and registering
 * all supplied contacts as members of a single household.
 */
public with sharing class HouseholdService {

    /**
     * Creates one NPSP Household Account and inserts every contact in
     * {@code members} as a member of that household.  The first contact
     * is set as the household's primary contact so that NPSP's naming
     * and greeting logic can generate the household name automatically.
     *
     * @param members  Contacts to register (new, no Id, no AccountId).
     * @return  The Id of the newly-created Household Account.
     */
    public static Id createHousehold(List<Contact> members) {

        // ── Guard clause ──────────────────────────────────────────────
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'createHousehold requires at least one Contact.'
            );
        }

        // ── 1. Resolve the Household record type (no hard-coded Id) ──
        Id hhRecordTypeId = [
            SELECT Id
            FROM   RecordType
            WHERE  SObjectType  = 'Account'
              AND  DeveloperName = 'HH_Account'
            LIMIT  1
        ].Id;

        // ── 2. Create the household Account ───────────────────────────
        //    •  Correct record type → NPSP identifies it as a household.
        //    •  Name intentionally omitted → NPSP trigger/Flow will
        //       generate the household name and greeting.
        //    •  Primary contact set later so that naming fires on the
        //       Account UPDATE (NPSP regenerates the name when
        //       npe01__One2OneContact__c changes).
        Account household = new Account(RecordTypeId = hhRecordTypeId);
        insert household;

        // ── 3. Insert all contacts linked to the single household ─────
        //    Contacts are never inserted without an AccountId, so NPSP's
        //    auto-household-creation logic (if enabled) cannot spawn
        //    extra "orphan" households.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        insert members;

        // ── 4. Set the primary contact ─────────────────────────────────
        //    Update only the primary-contact field so the account Name
        //    (already populated by NPSP on insert) is not overwritten.
        Account primaryContactUpdate = new Account(
            Id                              = household.Id,
            npe01__One2OneContact__c        = members[0].Id
        );
        update primaryContactUpdate;

        return household.Id;
    }
}
