public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) return;

        // ── Gather unique IDs for bulk queries ──────────────────────────────
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ── SOQL 1: Opportunities (amount + primary contact for validation) ─
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // ── SOQL 2: Existing Opportunity Contact Roles ──────────────────────
        // Key = OpportunityId : ContactId : Role  → lets us detect an existing
        // OCR that already carries the desired role.
        Map<String, OpportunityContactRole> ocrByTriple = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ]) {
            ocrByTriple.put(
                ocr.OpportunityId + ':' + ocr.ContactId + ':' + ocr.Role,
                ocr
            );
        }

        // ── SOQL 3: Existing Partial Soft Credits ───────────────────────────
        // Key = OpportunityId : ContactId  (one SC per pair, per requirement)
        Map<String, npsp__Partial_Soft_Credit__c> scByPair = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c sc : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            scByPair.put(sc.npsp__Opportunity__c + ':' + sc.npsp__Contact__c, sc);
        }

        // ── Validate every request BEFORE any DML ───────────────────────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact on Opportunity ' + req.opportunityId
                );
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for Opportunity ' + req.opportunityId +
                    ' / Contact ' + req.contactId
                );
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds Opportunity amount ' + opp.Amount +
                    ' for Opportunity ' + req.opportunityId
                );
            }
        }

        // ── First pass: determine which OCRs must be created ────────────────
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        // Track the OCR (existing or to-be-created) for each request index
        Map<Integer, OpportunityContactRole> reqToOcr = new Map<Integer, OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            String key = req.opportunityId + ':' + req.contactId + ':' + req.role;

            OpportunityContactRole ocr = ocrByTriple.get(key);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                ocrsToInsert.add(ocr);
            }
            reqToOcr.put(i, ocr);
        }

        // ── DML 1: Create missing Opportunity Contact Roles ─────────────────
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // ── Second pass: build Partial Soft Credit records ──────────────────
        List<npsp__Partial_Soft_Credit__c> scsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> scsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            OpportunityContactRole ocr = reqToOcr.get(i);

            String scKey = req.opportunityId + ':' + req.contactId;
            npsp__Partial_Soft_Credit__c existing = scByPair.get(scKey);

            if (existing != null) {
                // Update in place – same object, no duplicates
                existing.npsp__Amount__c         = req.amount;
                existing.npsp__Role_Name__c      = req.role;
                existing.npsp__Contact_Role_ID__c = ocr.Id;
                scsToUpdate.add(existing);
            } else {
                scsToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c    = req.opportunityId,
                    npsp__Contact__c        = req.contactId,
                    npsp__Amount__c         = req.amount,
                    npsp__Role_Name__c      = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                ));
            }
        }

        // ── DML 2: Insert new Partial Soft Credits ──────────────────────────
        if (!scsToInsert.isEmpty()) {
            insert scsToInsert;
        }

        // ── DML 3: Update existing Partial Soft Credits ─────────────────────
        if (!scsToUpdate.isEmpty()) {
            update scsToUpdate;
        }
    }
}
```

**Design notes (for the reviewer):**

| Constraint | How it is met |
|---|---|
| ≤ 4 SOQL | 3 queries total (Opportunity, OpportunityContactRole, Partial_Soft_Credit__c) regardless of request count. |
| ≤ 4 DML | At most 3 DML statements (insert OCRs → insert SCs → update SCs); many of these may be skipped at runtime. |
| Validation before DML | The entire validation loop runs to completion before the first DML; a `SoftCreditException` aborts with zero records written. |
| No duplicate soft credits | A pre-query builds a `scByPair` map keyed on `(Opportunity, Contact)`. If a hit exists, the object is mutated and sent through a single `update`. |
| One OCR per desired role | The triple key `(OpportunityId : ContactId : Role)` ensures an existing OCR with the same role is reused; a new OCR is only inserted when that exact combination is absent. |
| Primary-contact exclusion | Checked against `npsp__Primary_Contact__c` from the Opportunity query before any DML. |
| Bulk-safe | All work is done on collections; no SOQL/DML inside per-record loops. |

