/**
 * Converts a pledge (open donation) into a monthly installment plan.
 *
 * Replaces all non-history payments on an Opportunity with a set of
 * monthly installments whose amounts sum exactly to the outstanding balance.
 */
public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * @param opportunityId   the pledge Opportunity to restructure
     * @param numberOfPayments  how many installments to create (must be >= 1)
     * @param firstPaymentDate  date of the first installment; subsequent
     *                          installments are one calendar month apart
     * @return  the newly inserted payment records in schedule order
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ── Validate BEFORE any DML so we never "change something then throw" ──

        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be at least 1.'
            );
        }

        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM   Opportunity
            WHERE  Id = :opportunityId
            LIMIT  1
        ];

        if (opp == null) {
            throw new PaymentPlanException(
                'Opportunity not found.'
            );
        }

        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot restructure payments on a closed Opportunity.'
            );
        }

        // ── Gather existing payments ──

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM   npe01__OppPayment__c
            WHERE  npe01__Opportunity__c = :opportunityId
        ];

        Decimal outstanding = (opp.Amount == null)
                                  ? (Decimal)0
                                  : opp.Amount;

        List<npe01__OppPayment__c> toDelete =
            new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c pmt : existingPayments) {
            if (pmt.npe01__Paid__c || pmt.npe01__Written_Off__c) {
                // History – reduce the outstanding pool but leave the record.
                if (pmt.npe01__Payment_Amount__c != null) {
                    outstanding -= pmt.npe01__Payment_Amount__c;
                }
            } else {
                // Non-history – will be replaced.
                toDelete.add(pmt);
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero.'
            );
        }

        // ── DML: remove old non-history payments, then create the plan ──

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // Per-installment amount, floored to the cent.
        Decimal perPayment =
            (outstanding / numberOfPayments).setScale(2, RoundingMode.DOWN);

        // Remainder that the last installment must absorb.
        Decimal remainder =
            outstanding - perPayment * (numberOfPayments - 1);

        List<npe01__OppPayment__c> newPayments =
            new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c pmt = new npe01__OppPayment__c();
            pmt.npe01__Opportunity__c   = opportunityId;
            pmt.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            pmt.npe01__Paid__c           = false;
            pmt.npe01__Written_Off__c    = false;

            if (i == numberOfPayments - 1) {
                // Last installment absorbs the rounding remainder
                // so the total equals the outstanding amount exactly.
                pmt.npe01__Payment_Amount__c = (i == 0)
                    ? outstanding
                    : remainder;
            } else {
                pmt.npe01__Payment_Amount__c = perPayment;
            }

            newPayments.add(pmt);
        }

        insert newPayments;

        return newPayments;
    }
}
