public class FamilyService {

    /**
     * Creates NPSP Parent/Child relationship pairs for the supplied
     * childId → parentId map.  For each pair two Relationship records are
     * created (one in each direction) so that both contacts see the correct
     * type on their related-lists.
     *
     * Bulk-safe: at most 2 SOQL queries and 1 DML regardless of map size.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // ── guard ──────────────────────────────────────────────────────────
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── collect ids & validate pairs ───────────────────────────────────
        Set<Id> childIds    = new Set<Id>();
        Set<Id> parentIds   = new Set<Id>();
        Set<Id> allContactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // ── SOQL 1 – child gender (needed to pick reciprocal type) ─────────
        Map<Id, String> genderByChildId = new Map<Id, String>();
        for (Contact c : [
            SELECT Id, Gender
            FROM   Contact
            WHERE  Id IN :childIds
        ]) {
            genderByChildId.put(c.Id, c.Gender);
        }

        // ── SOQL 2 – pre-existing relationships among the contact set ──────
        //    Any relationship in EITHER direction causes the pair to be skipped.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM   npe4__Relationship__c
            WHERE  npe4__Contact__c       IN :allContactIds
              AND  npe4__RelatedContact__c IN :allContactIds
        ]) {
            // key = "contactId,relatedContactId"
            existingPairKeys.add(
                String.valueOf(rel.npe4__Contact__c) + ','
              + String.valueOf(rel.npe4__RelatedContact__c)
            );
        }

        // ── build new records (max 2 per pair) ─────────────────────────────
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        // Track pairs already handled *within this call* to avoid intra-batch dupes
        Set<String> batchPairKeys = new Set<String>();

        for (Id childId : childIds) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;

            // Build the two directional keys for this pair
            String childToParent = String.valueOf(childId)  + ',' + String.valueOf(parentId);
            String parentToChild = String.valueOf(parentId) + ',' + String.valueOf(childId);

            // Skip if a relationship already exists in the DB (either direction)
            if (existingPairKeys.contains(childToParent)
             || existingPairKeys.contains(parentToChild)) {
                continue;
            }

            // Skip if already created earlier in this same batch
            if (batchPairKeys.contains(childToParent)
             || batchPairKeys.contains(parentToChild)) {
                continue;
            }

            batchPairKeys.add(childToParent);
            batchPairKeys.add(parentToChild);

            // Determine reciprocal type from the child's gender
            String childGender = genderByChildId.get(childId);
            String recipType;
            if (childGender == 'Male') {
                recipType = 'Son';
            } else if (childGender == 'Female') {
                recipType = 'Daughter';
            } else {
                // Neutral, Non-Binary, Other, Unknown, blank, null …
                recipType = 'Child';
            }

            // Record A – on the CHILD's view: "my relationship to <parent> is Parent"
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = 'Parent',
                npe4__Status__c         = 'Current'
            ));

            // Record B – on the PARENT's view: "my relationship to <child> is Son/Daughter/Child"
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c           = recipType,
                npe4__Status__c         = 'Current'
            ));
        }

        // ── DML (single call) ──────────────────────────────────────────────
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
