/**
 * Trigger Action: Normalizes Lead contact info on before-insert.
 *
 * Registered via Trigger_Action__mdt record "TA_Lead_NormalizeContactInfo" (Order 10).
 * Called by the Trigger Actions Framework (TAF) from LeadTrigger before-insert.
 *
 * Rules:
 *   Email      – trim + lowercase (null stays null)
 *   Company    – trim
 *   LeadSource – default to "Web" when blank; existing value is kept
 *
 * No SOQL, no DML – mutates records in place so the first (and only) DML already
 * contains clean data.  Bulk-safe: iterates the full 200-record chunk.
 */
public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;

            // Email: trim + lowercase; null stays null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to "Web" when blank; keep existing value otherwise.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
