File: force-app/main/default/classes/TA_Opportunity_LogAmountChange.cls
```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Tracks Opportunity Ids for which a Task has already been created in this
    // transaction. Because TA_Opportunity_RoundAmount (Order 20) re-updates the
    // same records in the same execution, the after-update action fires a second
    // time for those records. Without this guard we would insert a duplicate Task.
    private static Set<Id> processedIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {

        // Build a lookup keyed by record Id so we can compare old vs new per record.
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        for (Opportunity opp : (List<Opportunity>) triggerOld) {
            oldMap.put(opp.Id, opp);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject s : triggerNew) {
            Opportunity oppNew = (Opportunity) s;
            Opportunity oppOld = oldMap.get(oppNew.Id);
            if (oppOld == null) {
                continue;
            }

            // Only act when Amount actually changed (handles null ↔ value correctly).
            if (oppNew.Amount == oppOld.Amount) {
                continue;
            }

            // Skip if we already logged this Opportunity earlier in the transaction
            // (i.e. the second trigger invocation caused by RoundAmount).
            if (processedIds.contains(oppNew.Id)) {
                continue;
            }

            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId  = oppNew.Id,
                Status  = 'Completed'
            ));

            processedIds.add(oppNew.Id);
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
